sol=[]
for a in range(5):
    for p in range(40):
        x=p//10; y=p%10
        sol.append((y-a*x)%10)
print(sol)
# verify
ok=True
for w in range(5):
    counts=[0]*10
    for p in range(40): counts[sol[w*40+p]]+=1
    if counts != [4]*10: print('bad counts',w,counts); ok=False
seen={}
for w in range(5):
    groups={g:[] for g in range(10)}
    for p in range(40): groups[sol[w*40+p]].append(p)
    for g,players in groups.items():
        for i in range(len(players)):
            for j in range(i+1,len(players)):
                pair=(players[i],players[j])
                if pair in seen: print('repeat',pair,seen[pair],(w,g)); ok=False
                seen[pair]=(w,g)
print('ok',ok,'pairs',len(seen))
